package com.mygo.music;

import android.app.*;
import android.content.*;
import android.content.res.Configuration;
import android.graphics.Bitmap;
import android.os.SystemClock;
import android.webkit.*;
import android.webkit.CookieManager;
import org.json.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

/** A p_skey-only page previously looked logged in while gallery authorization was prohibited. */
final class QQWebsiteChecks {
    final Instrumentation test;final Context context;final CompletionChecks helper;
    QQWebsiteChecks(Instrumentation test){this.test=test;context=test.getTargetContext();helper=new CompletionChecks(test);}
    static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    String asset()throws Exception{try(InputStream in=test.getContext().getAssets().open("qqmusic.js");ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}
    String adapted()throws Exception{File root=new File(context.getCacheDir(),"qq-web-adapter");File dist=new File(root,"dist");dist.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(root,"plugin.json"))){out.write("{\"id\":\"qqmusic\",\"main\":\"dist/index.js\"}".getBytes("UTF-8"));}File file=new File(dist,"index.js");String original=asset();try(FileOutputStream out=new FileOutputStream(file)){out.write(original.getBytes("UTF-8"));}PluginAdapters adapter=new PluginAdapters(root);check(adapter.qqWebLogin,"known QQ bundled entry was not adapted");String source;try(InputStream in=adapter.open(file);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);source=out.toString("UTF-8");}check(PluginIdentity.read(file).equals(original),"QQ original installation was modified");try(FileOutputStream out=new FileOutputStream(file)){out.write((original+"\n").getBytes("UTF-8"));}check(!new PluginAdapters(root).qqWebLogin,"unknown QQ revision enabled website adaptation");PluginArchive.delete(root);return source;}
    PluginRuntime runtime(PluginManager manager,String id)throws Exception{return (PluginRuntime)((Map<?,?>)FullPortChecks.field(manager,"runtimes")).get(id);}
    PluginRuntime browser(PluginManager manager,String id)throws Exception{PluginRuntime[] value={null};helper.await(()->{value[0]=runtime(manager,id);return value[0]!=null&&FullPortChecks.field(value[0],"browserView")!=null&&((WebView)FullPortChecks.field(value[0],"browserView")).getProgress()==100;},"website login did not load");return value[0];}
    void clickWebsite(PluginRuntime runtime){test.runOnMainSync(()->{try{((WebView)FullPortChecks.field(runtime,"browserView")).evaluateJavascript("document.getElementById('complete').click()",null);}catch(Exception e){throw new RuntimeException(e);}});}
    void run()throws Exception{
        BrowserCookieGate gate=new BrowserCookieGate(new JSONObject().put("untilAny",new JSONArray().put(new JSONArray().put("uin").put("qqmusic_uin")).put(new JSONArray().put("qqmusic_key").put("qm_keyst"))));check(!gate.ready("uin=2468; p_skey=ordinary")&&!gate.ready("uin=2468; qm_keyst="),"ordinary or empty cookies completed music login");check(gate.ready("qqmusic_uin=2468; qm_keyst=Q_music"),"valid alternative cookie names rejected");
        String id="qq-web-fixture";helper.cleanup(id);MainActivity activity=(MainActivity)test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));PluginManager manager=new PluginManager(activity);PlaybackService[] service={null};helper.await(()->{service[0]=(PlaybackService)FullPortChecks.field(activity,"playbackService");return service[0]!=null;},"QQ web player service missing");
        try(Server server=new Server()){
            String prefix="const __realFetch=globalThis.fetch;globalThis.fetch=(url,init)=>__realFetch(String(url).replace('https://u.y.qq.com','"+server.base()+"'),init);const __realWeb=host.webSignIn;host.webSignIn=options=>__realWeb({...options,url:'"+server.base()+"/login',cookiesOf:'"+server.base()+"/'});\n";
            helper.install(manager,id,"stream",new JSONArray(),prefix+adapted());File manifest=new File(context.getFilesDir(),"plugins/"+id+"/plugin.json");JSONObject config=new JSONObject(PluginIdentity.read(manifest)).put("permissions",new JSONObject().put("network",new JSONArray().put("127.0.0.1")));try(FileOutputStream out=new FileOutputStream(manifest)){out.write(config.toString().getBytes("UTF-8"));}context.getSharedPreferences("library",0).edit().putBoolean("plugin_network_"+id,true).commit();
            CountDownLatch finished=new CountDownLatch(1);boolean[] ok={false};String[] result={""};manager.export(id,"signIn",new JSONObject(),(success,raw)->{ok[0]=success;result[0]=raw;finished.countDown();});PluginRuntime runtime=browser(manager,id);SystemClock.sleep(800);check(finished.getCount()==1,"p_skey-only website was accepted as music login");helper.await(()->activity.getResources().getConfiguration().orientation==Configuration.ORIENTATION_PORTRAIT,"website login not usable in portrait");PluginRuntime firstPage=runtime;int[] viewport={0,0};boolean[] gallery={false};try{helper.await(()->{AlertDialog dialog=(AlertDialog)FullPortChecks.field(firstPage,"browserDialog");gallery[0]=dialog.getButton(AlertDialog.BUTTON_NEUTRAL)!=null&&dialog.getButton(AlertDialog.BUTTON_NEUTRAL).getVisibility()==android.view.View.VISIBLE;WebView view=(WebView)FullPortChecks.field(firstPage,"browserView");viewport[0]=view.getWidth();viewport[1]=view.getHeight();return viewport[0]>200&&viewport[1]>context.getResources().getDisplayMetrics().heightPixels*.45;},"website viewport collapsed");check(!gallery[0],"website still offers gallery authorization");}finally{System.out.println("QQ_WEBSITE_VIEWPORT: "+viewport[0]+"x"+viewport[1]+" screen="+context.getResources().getDisplayMetrics().heightPixels);
            Bitmap screenshot=test.getUiAutomation().takeScreenshot();if(screenshot!=null){File qa=new File(context.getExternalFilesDir(null),"qa");qa.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(qa,"qq-official-login.png"))){screenshot.compress(Bitmap.CompressFormat.PNG,100,out);}finally{screenshot.recycle();}}}
            clickWebsite(runtime);check(finished.await(15,TimeUnit.SECONDS)&&ok[0],"website credential not validated: "+result[0]);check(new JSONObject(result[0]).getString("id").equals("2468")&&server.profileVerified,"original QQ account verification missing");helper.await(()->activity.getResources().getConfiguration().orientation==Configuration.ORIENTATION_LANDSCAPE,"player orientation was not restored");String saved=context.getSharedPreferences("plugin_data_"+id,0).getString("qqmusic.auth.v1","");check(new JSONObject(saved).optBoolean("web"),"verified website credential not saved in original source storage");
            JSONArray queue=new JSONArray().put(new JSONObject().put("uri","plugin://"+id+"?id=web-song").put("title","website-authenticated audio"));test.runOnMainSync(()->{try{PlaybackService.startQueue(activity,queue,0,0,80,false,false,"standard");}catch(Exception e){throw new RuntimeException(e);}});helper.await(()->service[0].snapshot().playing&&service[0].snapshot().position>180,"website credential did not reach native playback: "+service[0].snapshot().error);check(server.vkeyVerified,"web music key not sent to vkey request");test.runOnMainSync(service[0]::stopPlayback);
            server.reject=true;CountDownLatch denied=new CountDownLatch(1);manager.export(id,"signIn",new JSONObject(),(success,raw)->{ok[0]=success;denied.countDown();});runtime=browser(manager,id);clickWebsite(runtime);check(denied.await(15,TimeUnit.SECONDS)&&!ok[0],"unverified website cookie was accepted");check(saved.equals(context.getSharedPreferences("plugin_data_"+id,0).getString("qqmusic.auth.v1","")),"failed profile validation overwrote previous source credential");helper.await(()->activity.getResources().getConfiguration().orientation==Configuration.ORIENTATION_LANDSCAPE,"failed login did not restore player layout");
            CountDownLatch cancelled=new CountDownLatch(1);manager.export(id,"signIn",new JSONObject(),(success,raw)->{ok[0]=success;cancelled.countDown();});PluginRuntime cancel=browser(manager,id);test.runOnMainSync(()->{try{((AlertDialog)FullPortChecks.field(cancel,"browserDialog")).getButton(AlertDialog.BUTTON_NEGATIVE).performClick();}catch(Exception e){throw new RuntimeException(e);}});check(cancelled.await(10,TimeUnit.SECONDS)&&!ok[0],"website cancellation did not stop sign-in");helper.await(()->activity.getResources().getConfiguration().orientation==Configuration.ORIENTATION_LANDSCAPE,"cancelled login did not restore player layout");String[] cookies={null};test.runOnMainSync(()->cookies[0]=CookieManager.getInstance().getCookie(server.base()));check(cookies[0]==null||cookies[0].isEmpty(),"temporary website cookie leaked after cancellation");
            System.out.println("MYGO_QQ_WEB_LOGIN_OK: original pinned QQ source, no gallery handoff, partial cookie rejection, original account validation before persistence, website music key in native audio playback, failed validation/cancel preserve prior credential, portrait viewport and landscape restoration");
        }finally{test.runOnMainSync(()->{service[0].stopPlayback();manager.close();activity.finish();});helper.cleanup(id);context.getSharedPreferences("library",0).edit().remove("plugin_network_"+id).commit();}
    }
    final class Server implements AutoCloseable {
        final ServerSocket server=new ServerSocket(0);final ExecutorService workers=Executors.newCachedThreadPool();volatile boolean closed,reject,profileVerified,vkeyVerified;
        Server()throws Exception{Thread thread=new Thread(()->{while(!closed)try{Socket socket=server.accept();workers.execute(()->serve(socket));}catch(Exception ignored){}});thread.setDaemon(true);thread.start();}
        String base(){return "http://127.0.0.1:"+server.getLocalPort();}
        void serve(Socket socket){try(Socket client=socket){client.setSoTimeout(10000);BufferedReader in=new BufferedReader(new InputStreamReader(client.getInputStream(),"UTF-8"));String first=in.readLine();if(first==null)return;String path=new URI(first.split(" ")[1]).getPath(),line;Map<String,String> headers=new HashMap<>();while((line=in.readLine())!=null&&!line.isEmpty()){int colon=line.indexOf(':');if(colon>0)headers.put(line.substring(0,colon).toLowerCase(Locale.ROOT),line.substring(colon+1).trim());}int length=Integer.parseInt(headers.getOrDefault("content-length","0"));char[] body=new char[length];int count=0,n;while(count<length&&(n=in.read(body,count,length-count))>0)count+=n;byte[] data;String type="application/json",cookies="";
            if(path.equals("/login")){cookies="Set-Cookie: uin=o0002468; Path=/; HttpOnly\r\nSet-Cookie: p_skey=ordinary-only; Path=/; HttpOnly\r\n";type="text/html";data="<!doctype html><meta name='viewport' content='width=device-width'><h1>Official website fixture</h1><p>Ordinary QQ cookie is not a music credential.</p><button id='complete' onclick=\"location.href='/complete'\">Complete website login</button>".getBytes("UTF-8");}
            else if(path.equals("/complete")){cookies="Set-Cookie: qqmusic_key=Q_web-fixture; Path=/; HttpOnly\r\n";type="text/html";data="<!doctype html><h1>Music session issued</h1>".getBytes("UTF-8");}
            else if(path.equals("/audio.mp3")){data=BackgroundPlaybackChecks.wav(8000);type="audio/wav";}
            else{JSONObject request=new JSONObject(new String(body,0,count)),comm=request.getJSONObject("comm"),call=request.getJSONObject("req_0"),answer=new JSONObject();String method=call.getString("method");boolean authenticated=comm.optInt("ct")==24&&comm.optString("authst").equals("Q_web-fixture")&&comm.optString("qq").equals("2468")&&comm.optInt("tmeLoginType")==2&&headers.getOrDefault("cookie","").contains("qm_keyst=Q_web-fixture");
                if(method.equals("GetLoginUserInfo")){profileVerified=authenticated&&headers.getOrDefault("user-agent","").equals("Mozilla/5.0");answer.put("info",new JSONObject().put("nick","Verified website fixture"));}
                else if(method.equals("get_song_detail_yqq"))answer.put("track_info",new JSONObject().put("mid","web-song").put("file",new JSONObject().put("media_mid","web-media").put("size_128mp3",256044)));
                else if(method.equals("CgiGetVkey")){vkeyVerified=authenticated&&call.optString("module").equals("vkey.GetVkeyServer")&&call.getJSONObject("param").optInt("loginflag")==1&&call.getJSONObject("param").optString("uin").equals("2468");answer.put("midurlinfo",new JSONArray().put(new JSONObject().put("songmid","web-song").put("purl",base()+"/audio.mp3"))).put("sip",new JSONArray().put("https://dl.stream.qqmusic.qq.com/"));}
                int code=reject||!authenticated?1000:0;data=new JSONObject().put("code",0).put("req_0",new JSONObject().put("code",code).put("data",answer)).toString().getBytes("UTF-8");}
            int start=0,end=data.length-1,status=200;String range=headers.get("range");if(range!=null&&range.matches("bytes=[0-9]+-[0-9]*")){String[] pieces=range.substring(6).split("-",-1);start=Integer.parseInt(pieces[0]);if(!pieces[1].isEmpty())end=Math.min(end,Integer.parseInt(pieces[1]));status=206;}OutputStream out=client.getOutputStream();out.write(("HTTP/1.1 "+status+" OK\r\nContent-Type: "+type+"\r\n"+cookies+"Content-Length: "+(end-start+1)+"\r\n"+(status==206?"Content-Range: bytes "+start+"-"+end+"/"+data.length+"\r\n":"")+"Connection: close\r\n\r\n").getBytes("US-ASCII"));out.write(data,start,end-start+1);out.flush();
        }catch(Exception ignored){}}
        public void close(){closed=true;try{server.close();}catch(IOException ignored){}workers.shutdownNow();}
    }
}
